/**
 * The testnet exchange's city markets: 79 US metros (Zillow Home Value Index) and 21 UK cities (UK House Price
 * Index). The list itself is generated by scripts/gen-markets.mjs into markets.generated.ts.
 */

export type CatalogueSource = { kind: "zillow"; regionId: number } | { kind: "ukhpi"; region: string };

export type CatalogueMarket = {
  /** Market id; also the on-chain key (bytes32 of this string). */
  id: string;
  city: string;
  /** US state, or the UK nation (ENG, SCT, WLS, NIR). */
  region: string;
  country: string;
  source: CatalogueSource;
  /** Latest reading in USD when the list was generated. */
  base: number;
};

export { CATALOGUE, GBP_USD } from "./markets.generated";
